CREATE TYPE "RoleKey" AS ENUM ('SUPER_ADMIN','OWNER','COMPANY_ADMIN','MANAGER','SALES_PRICING','OPERATIONS','DG_USER','FINANCE','READ_ONLY','DEMO','MARKETPLACE_CUSTOMER');
CREATE TYPE "SubscriptionStatus" AS ENUM ('TRIAL','ACTIVE','PAST_DUE','CANCELED','EXPIRED');
CREATE TYPE "ApplicationKey" AS ENUM ('PRICING','CONTRACT_KYC','OPERATIONS','DG_VAULT','MARKETPLACE');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT,"emailVerifiedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Company" ("id" TEXT PRIMARY KEY,"legalName" TEXT NOT NULL,"tradingName" TEXT,"country" TEXT NOT NULL,"emirate" TEXT,"tradeLicenseNumber" TEXT,"tradeLicenseExpiry" TIMESTAMP(3),"vatTrn" TEXT,"address" TEXT,"website" TEXT,"expectedUsers" INTEGER,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Membership" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"companyId" TEXT NOT NULL,"role" "RoleKey" NOT NULL DEFAULT 'READ_ONLY',UNIQUE("userId","companyId"),FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,FOREIGN KEY("companyId") REFERENCES "Company"("id") ON DELETE CASCADE);
CREATE TABLE "Application" ("id" TEXT PRIMARY KEY,"key" "ApplicationKey" NOT NULL UNIQUE,"name" TEXT NOT NULL,"isMarketplace" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "Plan" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"code" TEXT NOT NULL UNIQUE);
CREATE TABLE "PlanApplication" ("planId" TEXT NOT NULL,"applicationId" TEXT NOT NULL,PRIMARY KEY("planId","applicationId"),FOREIGN KEY("planId") REFERENCES "Plan"("id") ON DELETE CASCADE,FOREIGN KEY("applicationId") REFERENCES "Application"("id") ON DELETE CASCADE);
CREATE TABLE "Subscription" ("id" TEXT PRIMARY KEY,"companyId" TEXT NOT NULL,"planId" TEXT,"status" "SubscriptionStatus" NOT NULL DEFAULT 'TRIAL',"simulator" BOOLEAN NOT NULL DEFAULT true,"startsAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endsAt" TIMESTAMP(3),FOREIGN KEY("companyId") REFERENCES "Company"("id") ON DELETE CASCADE,FOREIGN KEY("planId") REFERENCES "Plan"("id"));
CREATE TABLE "Entitlement" ("id" TEXT PRIMARY KEY,"subscriptionId" TEXT NOT NULL,"applicationId" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,UNIQUE("subscriptionId","applicationId"),FOREIGN KEY("subscriptionId") REFERENCES "Subscription"("id") ON DELETE CASCADE,FOREIGN KEY("applicationId") REFERENCES "Application"("id"));
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL UNIQUE,"ipHash" TEXT,"userAgent" TEXT,"expiresAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"companyId" TEXT,"userId" TEXT,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("userId") REFERENCES "User"("id"));
CREATE INDEX "AuditLog_companyId_createdAt_idx" ON "AuditLog"("companyId","createdAt");
